"""Second sound-design curriculum. Preserves guide coverage; adds applied decisions.

Old holdouts are now development diagnostics. Fresh gate questions are never trained.
References inform scenario selection, not claims of recovered audio stems.
"""
from pathlib import Path
import json,hashlib,sys,copy
sys.path.insert(0,str(Path(__file__).resolve().parent))
import corpus

