GATE=[
 ('cafe_title','A narrator explains a recipe in a cafe. Four small labels appear, then one large heading lands. Existing music must stay. Give a practical sound plan.', 'Retain the music and speech; establish only evidenced cafe ambience; selectively emphasize the major heading, avoiding a click for each label. Use a relevant light entrance or impact with a natural tail and verify masking.', 'speech priority; selective typography; preserve song'),
 ('tram_world','A tram moves past the camera for 4.2 seconds under an interview. Only weak original vehicle audio is present. How should its sound behave?', 'Use a compatible sustained tram pass-by with perspective and natural tail, plus supported environment if needed. Keep interview intelligible and do not replace travel with short clicks or invent a horn.', 'sustained cause; perspective; dialogue priority'),
 ('dry_irony','A creator shows a nearly deserted shopping arcade and says sarcastically that it is packed. Choose ambience and an editorial response.', 'Retain quiet plausible arcade air, not crowd noise from the word packed. A small dry comic response or pause may fit; absolute silence is not required. Preserve speech.', 'context beats keyword; no absolute silence; restrained irony'),
 ('leather_action','A hand pulls a leather bag zipper closed over 1.9 seconds. A click file and a 3-second zipper recording are available. Choose a treatment.', 'Choose a relevant zipper window across the action with its natural tail; align meaningful movement and preserve source bounds. Reject generic click substitution. Mix at believable proximity.', 'source identity; natural duration'),
 ('headphone_truth','Only a screenshot and an audio-energy curve are available for a reference. Can you teach the model that it uses exactly three chimes and two bass hits?', 'No. Neither screenshot nor energy curve establishes instrument identities or stem count. Keep those unknown and inspect actual audio using suitable perception tools; separate proposed design from evidence.', 'no invented hearing; uncertainty'),
 ('overlay_preserve','The original clip already has an effective text swoosh and a song. A new planner proposes the same swoosh and another song at that moment. What do you do?', 'Reject duplicate coverage, preserve source once and owner music. Add only supported missing detail after listening; avoid unnecessary processing. Verify combined export has no duplicates.', 'source preservation; duplicate prevention'),
 ('unavailable_site','No local rain source is suitable. Freesound has no credentials and no website connector, Commons is enabled. What should the assistant do next?', 'Use the enabled Commons connector with a precise rain query, inspect license and audio, then select and align a suitable result. Do not pretend Freesound access or download success; report a missing source if no eligible result.', 'real tool access; retrieval; rights'),
 ('effect_tail','A suitable tonal accent has a brief attack and 1.6-second decay. The title settles in 0.3 seconds. Must the file be cut at 0.3?', 'No. Align the accent attack or intended peak to settling and retain the useful decay where it supports the scene and does not mask speech or the next event. Duration follows function, not a blanket short limit.', 'natural tail; speech check'),
]

def build(root):
    originals,coverage=corpus.build_corpus(root);rows=[]
    for row in originals:
        r=copy.deepcopy(row);r['source_kind']='revision_original';r['messages'][0]['content']=SYSTEM;rows.append(r)
    for i,case in enumerate(SCENARIOS):
        q,*parts=case
        answer='\n'.join(h+': '+p for h,p in zip(('Evidence','Choice','Timing','Mix','Check'),parts))
        # Deliberate curriculum weighting: three exposures, recorded explicitly.
        for exposure in range(3):
            rows.append(dict(id=f'applied-{i:02d}-exposure-{exposure}',source_kind='revision_scenario',
              curriculum_case=i,curriculum_exposure=exposure,synthetic=True,audio_quality_verified=False,
              messages=[dict(role='system',content=SYSTEM),dict(role='user',content=q),dict(role='assistant',content=answer)]))
    return rows,coverage

def write(root):
    out=Path(root)/'output/sound-training/20261030-revision2/dataset';out.mkdir(parents=True,exist_ok=True)
    rows,coverage=build(root)
    for name,data in [('train',rows),('holdout',[dict(id=i,rubric=r,audio_quality_verified=False,messages=[dict(role='system',content=SYSTEM),dict(role='user',content=q),dict(role='assistant',content=a)]) for i,q,a,r in GATE])]:
        (out/(name+'.jsonl')).write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in data),encoding='utf-8')
    (out/'coverage.json').write_text(json.dumps(coverage,indent=2),encoding='utf-8')
    receipt=dict(training_rows=len(rows),unique_original_lessons=len(rows)-3*len(SCENARIOS),unique_applied_cases=len(SCENARIOS),applied_exposures=3,
       fresh_gate_questions=len(GATE),previous_holdouts_now_development_only=True,source_guide_pages=40,reference_audio_labels_are_not_ground_truth=True,
       train_sha256=hashlib.sha256((out/'train.jsonl').read_bytes()).hexdigest())
    (out/'dataset-receipt.json').write_text(json.dumps(receipt,indent=2),encoding='utf-8');print(json.dumps(receipt))
if __name__=='__main__':write(Path(__file__).resolve().parents[2])
